    reg [1:0] state, next_state;
    parameter IDLE = 2'b00, COUNT = 2'b01, DONE = 2'b10;

    always @ (posedge clk) begin
        if(reset) begin
            state <= IDLE;
        end
        else begin
            state <= next_state;
        end
    end

    always @ (*) begin
        case(state)
            IDLE: begin
                if(data) begin
                    next_state = COUNT;
                end
                else begin
                    next_state = IDLE;
                end
            end
            COUNT: begin
                if(count_reg == 4'd9) begin
                    next_state = DONE;
                end
                else begin
                    next_state = COUNT;
                end
            end
            DONE: begin
                next_state = ack ? IDLE : DONE;
            end
            default: begin
                next_state = IDLE;
            end
        endcase
    end

    always @ (posedge clk) begin
        if(reset) begin
            count_reg <= 4'b0;
            counting_reg <= 1'b0;
            done_reg <= 1'b0;
        end
        else begin
            case(state)
                IDLE: begin
                    count_reg <= 4'b0;
                    counting_reg <= 1'b0;
                    done_reg <= 1'b0;
                end
                COUNT: begin
                    count_reg <= count_reg + 4'b1;
                    counting_reg <= 1'b1;
                    done_reg <= 1'b0;
                end
                DONE: begin
                    count_reg <= count_reg;
                    counting_reg <= 1'b0;
                    done_reg <= 1'b1;
                end
                default: begin
                    count_reg <= count_reg;
                    counting_reg <= counting_reg;
                    done_reg <= done_reg;
                end
            endcase
        end
    end

    assign count = count_reg;
    assign counting = counting_reg;
    assign done = done_reg;

endmodule


