	parameter IDLE = 3'd0;
	parameter LOAD = 3'd1;
	parameter SHIFT = 3'd2;
	parameter DONE = 3'd3;
	reg [2:0] present_state, next_state;
	reg [7:0] shift_reg;
	reg [3:0] counter;

	always @ (present_state or in or counter) begin
		case(present_state)
			IDLE: next_state = (in)? LOAD : IDLE;
			LOAD: next_state = SHIFT;
			SHIFT: next_state = (counter == 4'd8)? DONE : SHIFT;
			DONE: next_state = (in)? LOAD : IDLE;
		endcase
	end

	always @ (posedge clk) begin
		if(reset) begin
			present_state <= IDLE;
		end
		else begin
			present_state <= next_state;
		end
	end

	always @ (posedge clk) begin
		if(reset) begin
			shift_reg <= 8'b0;
		end
		else begin
			case(next_state)
				LOAD: shift_reg <= {in, shift_reg[7:1]};
				default: shift_reg <= shift_reg;
			endcase
		end
	end

	always @ (posedge clk) begin
		if(reset) begin
			counter <= 4'b0;
		end
		else begin
			case(next_state)
				SHIFT: counter <= counter + 4'b1;
				default: counter <= 4'b0;
			endcase
		end
	end

	assign done = (present_state == DONE);
	assign out_byte = shift_reg;

endmodule



